"powershell -Command "
Write-Output '=== 시스템 정보 ===';
Get-CimInstance Win32_ComputerSystem | Select-Object Manufacturer, Model | Format-List;

Write-Output '=== 마우스 / 포인터 설정 (레지스트리) ===';
Get-ItemProperty -Path 'HKCU:\Control Panel\Mouse' | Select-Object MouseSensitivity, MouseSpeed, MouseThreshold1, MouseThreshold2, SmoothMouseXCurve, SmoothMouseYCurve | Format-List;

Write-Output '=== 정밀 터치패드 설정 (레지스트리) ===';
if (Test-Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\PrecisionTouchPad') {
    Get-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\PrecisionTouchPad' | Format-List;
} else {
    Write-Output 'PrecisionTouchPad 레지스트리 키가 기본 경로에 없습니다.';
}

Write-Output '=== 연결된 마우스 및 터치패드 디바이스 ===';
Get-PnpDevice -Class 'Mouse' -Status 'OK' | Select-Object FriendlyName, InstanceId, Status | Format-Table;
Get-PnpDevice -Class 'HIDClass' -Status 'OK' | Where-Object { $_.FriendlyName -match 'Touch|Pad|Elan|Synaptics|I2C' } | Select-Object FriendlyName, InstanceId, Status | Format-Table;

Write-Output '=== 배터리 상태 (스웰링/노후화 간접 확인) ===';
Get-CimInstance Win32_Battery | Select-Object Name, DesignCapacity, FullChargeCapacity, EstimatedChargeRemaining, Status, BatteryStatus | Format-List;
""

"powershell -NoProfile -Command "
Get-PnpDevice -Class 'Mouse' | Format-Table -AutoSize;
Get-PnpDevice -Class 'HIDClass' | Where-Object { `$_.FriendlyName -match 'Touch|Pad|Synaptics|I2C|HID' } | Select-Object FriendlyName, Status | Format-Table -AutoSize;
""

"powershell -NoProfile -Command "
# 1. 정밀 터치패드 설정 변경
Set-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\PrecisionTouchPad' -Name 'AAPThreshold' -Value 0 -Type DWord;
Set-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\PrecisionTouchPad' -Name 'CursorSpeed' -Value 17 -Type DWord;

# 2. 마우스 감도 상향 조정 (8 -> 10)
Set-ItemProperty -Path 'HKCU:\Control Panel\Mouse' -Name 'MouseSensitivity' -Value '10';

# 3. 변경된 레지스트리 확인
Get-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\PrecisionTouchPad' | Select-Object AAPThreshold, CursorSpeed | Format-List;
Get-ItemProperty -Path 'HKCU:\Control Panel\Mouse' | Select-Object MouseSensitivity | Format-List;

# 4. Windows 시스템에 설정 즉시 브로드캐스트 (SystemParametersInfo)
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public class WinApi {
    [DllImport(\"user32.dll\", SetLastError = true)]
    public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, IntPtr pvParam, uint fWinIni);
}
'@

# SPI_SETMOUSESPEED = 0x0071, SPIF_UPDATEINIFILE = 0x01, SPIF_SENDCHANGE = 0x02
[WinApi]::SystemParametersInfo(0x0071, 0, [IntPtr]10, 3) | Out-Null;
Write-Output '설정 적용 완료';
""

"powershell -NoProfile -Command "
Write-Output '=== 1. 장치 관리자 오류 및 문제 코드 점검 ===';
$devices = Get-PnpDevice | Where-Object { `$_.Problem -ne 'CM_PROB_NONE' };
if (`$devices) {
    `$devices | Select-Object FriendlyName, Class, Problem, Status | Format-Table -AutoSize;
} else {
    Write-Output '모든 PnP 장치가 정상 상태(CM_PROB_NONE)입니다.';
}

Write-Output '=== 2. 터치패드 및 I2C 드라이버 상세 정보 ===';
Get-CimInstance Win32_PnPSignedDriver | Where-Object { `$_.DeviceClass -in @('MOUSE', 'HIDCLASS', 'SYSTEM') -and (`$_.Description -match 'Synaptics|I2C|Touch' -or `$_.DeviceName -match 'Synaptics|I2C|Touch') } | Select-Object DeviceName, DriverVersion, DriverDate, Manufacturer, IsSigned | Format-Table -AutoSize;

Write-Output '=== 3. 최근 7일간 터치패드/HID/I2C 관련 시스템 오류 로그 ===';
try {
    `$logs = Get-WinEvent -FilterHashtable @{LogName='System'; Level=1,2,3; StartTime=(Get-Date).AddDays(-7)} -ErrorAction SilentlyContinue | Where-Object { `$_.ProviderName -match 'HID|i2c|Synaptics|mouclass|i8042prt|Kernel-PnP' };
    if (`$logs) {
        `$logs | Select-Object -First 10 TimeCreated, ProviderName, LevelDisplayName, Message | Format-Table -AutoSize;
    } else {
        Write-Output '최근 7일간 터치패드/HID/I2C 관련 시스템 오류나 경고가 전혀 없습니다.';
    }
} catch {
    Write-Output '이벤트 로그 조회 완료 (오류 없음)';
}

Write-Output '=== 4. 배터리 상태 상세 (설계용량 대비 완충용량) ===';
powercfg /batteryreport /output \"$env:TEMP\battery_report.html\" | Out-Null;
if (Test-Path \"$env:TEMP\battery_report.html\") {
    `$html = Get-Content \"$env:TEMP\battery_report.html\" -Raw;
    if (`$html -match 'DESIGN CAPACITY.*?([\d,]+)\s*mWh.*?FULL CHARGE CAPACITY.*?([\d,]+)\s*mWh') {
        Write-Output \"설계 용량(Design): `$($matches[1]) mWh / 완충 용량(Full Charge): `$($matches[2]) mWh\";
    }
}
""

"powershell -NoProfile -Command @'
Write-Host "=== 1. 장치 관리자 오류 점검 ==="
$probDevices = Get-PnpDevice | Where-Object { $_.Problem -ne "CM_PROB_NONE" }
if ($probDevices) {
    $probDevices | Select-Object FriendlyName, Class, Problem, Status | Format-Table -AutoSize
} else {
    Write-Host "[정상] 모든 관련 하드웨어 장치에 문제 코드가 없습니다."
}

Write-Host "`n=== 2. 터치패드 & I2C 드라이버 상세 정보 ==="
Get-CimInstance Win32_PnPSignedDriver | Where-Object {
    $_.DeviceClass -in @('MOUSE', 'HIDCLASS', 'SYSTEM') -and 
    ($_.Description -match 'Synaptics|I2C|Touch' -or $_.DeviceName -match 'Synaptics|I2C|Touch')
} | Select-Object DeviceName, DriverVersion, DriverDate, Manufacturer, IsSigned | Format-Table -AutoSize

Write-Host "`n=== 3. 시스템 이벤트 로그 (HID/I2C/PnP 오류 검색) ==="
$events = Get-WinEvent -FilterHashtable @{LogName='System'; Level=1,2,3; StartTime=(Get-Date).AddDays(-7)} -ErrorAction SilentlyContinue | 
          Where-Object { $_.ProviderName -match 'HID|i2c|Synaptics|mouclass|i8042prt|Kernel-PnP' }
if ($events) {
    $events | Select-Object -First 10 TimeCreated, ProviderName, LevelDisplayName, Message | Format-Table -AutoSize
} else {
    Write-Host "[정상] 최근 7일간 터치패드/입력장치 관련 오류나 충돌 로그가 0건입니다."
}

Write-Host "`n=== 4. 배터리 상태 점검 (스웰링 간접 지표) ==="
powercfg /batteryreport /output "$env:TEMP\battery_report.html" | Out-Null
if (Test-Path "$env:TEMP\battery_report.html") {
    $raw = Get-Content "$env:TEMP\battery_report.html" -Raw
    if ($raw -match 'DESIGN CAPACITY[^\d]*([\d,]+)\s*mWh[\s\S]*?FULL CHARGE CAPACITY[^\d]*([\d,]+)\s*mWh') {
        Write-Host "설계 용량: $($matches[1]) mWh"
        Write-Host "완충 용량: $($matches[2]) mWh"
    } else {
        Write-Host "배터리 리포트 생성 완료"
    }
}
'@"

"powershell -ExecutionPolicy Bypass -Command "& {
    Write-Output '--- 1. PnP Error Devices ---'
    $errs = Get-PnpDevice | Where-Object { $_.Problem -ne 'CM_PROB_NONE' -and $_.Class -in @('Mouse','HIDClass','System') }
    if ($errs) { $errs | Format-Table } else { Write-Output 'No hardware errors found on input devices.' }

    Write-Output '--- 2. Touchpad Driver Info ---'
    Get-CimInstance Win32_PnPSignedDriver | Where-Object { $_.DeviceClass -in @('MOUSE','HIDCLASS') -and ($_.DeviceName -match 'Synaptics|I2C|Touch|Pad' -or $_.Description -match 'Synaptics|I2C|Touch|Pad') } | Select-Object DeviceName, DriverVersion, DriverDate, Manufacturer | Format-Table -AutoSize

    Write-Output '--- 3. Event Logs ---'
    $logs = Get-WinEvent -FilterHashtable @{LogName='System'; Level=1,2; StartTime=(Get-Date).AddDays(-7)} -ErrorAction SilentlyContinue | Where-Object { $_.ProviderName -match 'HID|i2c|Synaptics|mouclass' }
    if ($logs) { $logs | Format-Table } else { Write-Output 'No error logs found in the last 7 days.' }

    Write-Output '--- 4. Battery Capacity Check ---'
    powercfg /batteryreport /output \"$env:TEMP\battery_report.html\" | Out-Null
    $txt = Get-Content \"$env:TEMP\battery_report.html\" -Raw
    if ($txt -match 'DESIGN CAPACITY.*?(\d[\d,]*\s*mWh)[\s\S]*?FULL CHARGE CAPACITY.*?(\d[\d,]*\s*mWh)') {
        Write-Output \"Design Capacity: $($matches[1])\"
        Write-Output \"Full Charge Capacity: $($matches[2])\"
    }
}""

